<?php $isEdit=$product!==null; ?><div class="form-section"><form method="post" action="<?= e($isEdit?base_url('admin/product/edit/'.$product['id']):base_url('admin/product/add')) ?>" class="row g-3 mb-4"><?= csrf_field() ?><div class="col-md-4"><label class="form-label">SKU</label><input class="form-control" name="sku" value="<?= e($product['sku']??'') ?>" required></div><div class="col-md-8"><label class="form-label">Tên sản phẩm</label><input class="form-control" name="name" value="<?= e($product['name']??'') ?>" required></div><div class="col-md-6"><label class="form-label">Danh mục</label><select class="form-select" name="category_id" required><option value="">-- Chọn --</option><?php foreach($categories as $c): ?><option value="<?= (int)$c['id'] ?>" <?= isset($product['category_id'])&&(int)$product['category_id']===(int)$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach; ?></select></div><div class="col-md-6"><label class="form-label">Thương hiệu</label><input class="form-control" name="brand" value="<?= e($product['brand']??'') ?>"></div><div class="col-12"><label class="form-label">Mô tả</label><textarea class="form-control" name="description" rows="3"><?= e($product['description']??'') ?></textarea></div><div class="col-md-4"><label class="form-label">Giá</label><input class="form-control" type="number" min="1" name="price" value="<?= e($product['price']??'') ?>" required></div><div class="col-md-4"><label class="form-label">Tồn kho</label><input class="form-control" type="number" min="0" name="stock" value="<?= e($product['stock']??0) ?>" required></div><div class="col-md-4"><label class="form-label">Trạng thái</label><select class="form-select" name="status"><option value="active" <?= ($product['status']??'active')==='active'?'selected':'' ?>>Đang bán</option><option value="inactive" <?= ($product['status']??'')==='inactive'?'selected':'' ?>>Ngừng bán</option></select></div><div class="col-12 form-check ms-2"><input class="form-check-input" type="checkbox" name="is_featured" id="featured" <?= !empty($product['is_featured'])?'checked':'' ?>><label class="form-check-label" for="featured">Sản phẩm nổi bật</label></div><div class="col-12"><button class="btn btn-primary"><?= $isEdit?'Lưu thay đổi':'Thêm sản phẩm' ?></button> <a class="btn btn-secondary" href="<?= e(base_url('admin/product')) ?>">Quay lại</a></div></form></div>
<?php if($isEdit): ?><hr><h2 class="h5">Ảnh sản phẩm (<?= count($images) ?>/<?= UPLOAD_MAX_IMAGES ?>)</h2><div class="row row-cols-2 row-cols-md-4 g-3 mb-4"><?php foreach($images as $img): ?><div class="col"><div class="card h-100 <?= $img['is_primary']?'border-primary border-2':'' ?>"><img src="<?= e(product_image_url($img['file_name'],'thumb')) ?>" class="card-img-top" style="aspect-ratio:1/1;object-fit:cover" alt="<?= e($img['alt_text']) ?>"><div class="card-body p-2"><?php if($img['is_primary']): ?><span class="badge bg-primary mb-2">Ảnh đại diện</span><?php else: ?><form method="post" action="<?= e(base_url('admin/productImage/setPrimary')) ?>"><?= csrf_field() ?><input type="hidden" name="product_id" value="<?= (int)$product['id'] ?>"><input type="hidden" name="image_id" value="<?= (int)$img['id'] ?>"><button class="btn btn-sm btn-outline-primary w-100 mb-2">Đặt đại diện</button></form><?php endif; ?><form method="post" action="<?= e(base_url('admin/productImage/updateAlt')) ?>"><?= csrf_field() ?><input type="hidden" name="product_id" value="<?= (int)$product['id'] ?>"><input type="hidden" name="image_id" value="<?= (int)$img['id'] ?>"><input class="form-control form-control-sm mb-1" name="alt_text" value="<?= e($img['alt_text']) ?>" placeholder="Alt ảnh"><button class="btn btn-sm btn-outline-secondary w-100 mb-2">Lưu alt</button></form><?php if(!$img['is_primary']): ?><div class="d-flex gap-1 mb-2"><?php foreach(['up'=>'↑','down'=>'↓'] as $dir=>$label): ?><form method="post" action="<?= e(base_url('admin/productImage/reorder')) ?>"><?= csrf_field() ?><input type="hidden" name="product_id" value="<?= (int)$product['id'] ?>"><input type="hidden" name="image_id" value="<?= (int)$img['id'] ?>"><input type="hidden" name="direction" value="<?= $dir ?>"><button class="btn btn-sm btn-outline-dark"><?= $label ?></button></form><?php endforeach; ?></div><?php endif; ?><form method="post" action="<?= e(base_url('admin/productImage/delete')) ?>" onsubmit="return confirm('Xóa ảnh này?')"><?= csrf_field() ?><input type="hidden" name="product_id" value="<?= (int)$product['id'] ?>"><input type="hidden" name="image_id" value="<?= (int)$img['id'] ?>"><button class="btn btn-sm btn-outline-danger w-100">Xóa ảnh</button></form></div></div></div><?php endforeach; ?></div><?php if(count($images)<UPLOAD_MAX_IMAGES): ?><form class="col-md-8" method="post" enctype="multipart/form-data" action="<?= e(base_url('admin/productImage/upload')) ?>"><?= csrf_field() ?><input type="hidden" name="product_id" value="<?= (int)$product['id'] ?>"><label class="form-label">Chọn ảnh JPG/PNG/WEBP, tối đa 2MB mỗi ảnh; có thể chọn nhiều ảnh</label><input class="form-control mb-2" type="file" name="images[]" accept=".jpg,.jpeg,.png,.webp" multiple required><button class="btn btn-primary">Tải ảnh lên</button></form><?php else: ?><p class="text-muted">Đã đạt giới hạn 8 ảnh.</p><?php endif; ?><?php endif; ?>
